input.new_string:
{/* Adicionar produto — campo único, filtra digitando. Dropdown próprio
    (não datalist nativo — o popup do datalist estica pela largura do
    texto e vaza pra fora do modal, sem jeito de travar via CSS). */}
{produtosDisponiveis.length > 0 ? (
  <div className="relative">
    <input
      type="text"
      value={buscaProduto}
      onChange={(e) => setBuscaProduto(e.target.value)}
      placeholder="+ Adicionar produto..."
      className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] rounded-lg px-3 py-2 text-sm text-[#18181B] dark:text-[#F4F4F5] focus:outline-none focus:border-[#FF441F]"
    />
    {buscaProduto.trim() && (
      <div className="absolute left-0 right-0 top-full mt-1 max-h-48 overflow-y-auto border border-[#E4E4E7] dark:border-[#3F3F46] rounded-lg bg-white dark:bg-[#18181B] divide-y divide-[#E4E4E7] dark:divide-[#3F3F46] shadow-lg z-10">
        {produtosDisponiveis
          .filter((p) => p.name.toLowerCase().includes(buscaProduto.trim().toLowerCase()))
          .map((p) => (
            <button
              type="button"
              key={p.id}
              onClick={() => addItem(p.id)}
              className="w-full text-left px-3 py-2 text-sm text-[#18181B] dark:text-[#F4F4F5] hover:bg-gray-50 dark:hover:bg-gray-950/40 truncate"
            >
              {p.name} — {fmt(p.price)}
            </button>
          ))}
        {!produtosDisponiveis.some((p) => p.name.toLowerCase().includes(buscaProduto.trim().toLowerCase())) && (
          <p className="px-3 py-2 text-xs text-[#71717A] dark:text-[#A1A1AA]">Nenhum produto encontrado</p>
        )}
      </div>
    )}
  </div>
) : (
  <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Todos os produtos já foram adicionados</p>
)}

