857	  async pagar(id: number, restaurantId: number, formaPagamento: string, gorjetaValor?: number, valorRecebido?: number, gorjetaDireta?: boolean) {
858	    if (!formaPagamento) throw new BadRequestException('Informe a forma de pagamento');
859	
860	    const comanda = await this.buscarComanda(id, restaurantId);
861	    if (comanda.status !== 'fechada_garcom' && comanda.status !== 'aberta') {
862	      throw new BadRequestException('Comanda já foi paga ou cancelada');
863	    }
864	
865	    const { data: itens } = await this.supabase.client.from('order_items').select('quantity, unit_price, products(name)').eq('order_id', id);
866	    const subtotal = (itens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
867	    const totalFinal = subtotal - (comanda.desconto_valor ?? 0) + (comanda.acrescimo_valor ?? 0);
868	
869	    // Se já teve pagamento parcial (garçom ou caixa), só registra o que ainda falta —
870	    // o ledger de comanda_pagamentos fica completo pra conferência.
871	    const { saldo } = await this.salaoService.saldoDevedor(id);
872	    // Fechamento não cobre mais o saldo restante sozinho — o operador é obrigado a lançar
873	    // os pagamentos parciais (com a forma correta de cada um) até o saldo zerar antes de
874	    // poder fechar. Evita fechar tudo numa forma só quando o cliente pagou split.
875	    if (saldo > 0.01) {
876	      throw new BadRequestException('Saldo devedor pendente: registre os pagamentos até zerar o saldo antes de fechar a comanda');
877	    }
