881	    // A essa altura o saldo dos itens já está zerado — só falta cobrar a gorjeta (se houver).
882	    const valorACobrar = parseFloat((valorACobrarBase + taxaCartaoValor).toFixed(2));
883	    let troco: number | null = null;
