<div class="item-qtd">Qtd: ${i.quantity}</div>
${i.description ? `<div class="item-desc">Descrição: ${i.description}</div>` : ''}
${i.observacao ? `<div class="item-obs">Obs: ${i.observacao}</div>` : ''}
${idx < itens.length - 1 ? '<hr class="separador"/>' : ''}
`).join('')}
<hr/>
<script>
window.print();
try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}
</script>
</body></html>`;

  const frameId = `setor-frame-${Date.now()}`;
  const iframe = document.createElement('iframe');
  iframe.id = frameId;
  iframe.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
  document.body.appendChild(iframe);

  try {
    iframe.contentDocument.open();
    iframe.contentDocument.write(html);
    iframe.contentDocument.close();
  } catch {
    iframe.remove();
    const w = window.open('', '_blank', 'width=440,height=680');
    if (w) { w.document.write(html); w.document.close(); }
  }
};

  const recibo = await this.salaoService.imprimirReciboSeConfigurado(
    restaurantId, comanda,
    (itens ?? []).map((i: any) => ({ product_name: i.products?.name, quantity: i.quantity, unit_price: i.unit_price })),
    {
      subtotal,
      desconto: comanda.desconto_valor ?? 0,
      acrescimo: comanda.acrescimo_valor ?? 0,
      gorjeta,
      taxaCartao: taxaCartaoTotalRecibo,
      total: totalGeralRecibo,
      formaPagamento,
      trocoDado: troco && troco > 0 ? troco : 0,
    },
    pagamentos ?? [],
  );

  return {
    ok: true, total: parseFloat(totalFinal.toFixed(2)), total_geral: totalGeralRecibo,
    taxa_cartao_valor: taxaCartaoTotalRecibo, valor_cobrado: valorACobrar,
    troco, recibo, pagamentos: pagamentos ?? [],
  };
}

